# Windows twin of detect_local.sh. Runs ON THE USER'S COMPUTER through one machine Shell call (PowerShell 5.1+). Read-only.
#   & ([scriptblock]::Create(@'
#   ...this file...
#   '@)) -Clis claude,codex,pi,omp [-NoUserEnv]
# Tests whether the import_plan.py paths exist (names, never contents), runs `<cli> --version` (10 s cap), and prints
# the same JSON as detect_local.sh: {"os":"windows","home","clis":{...},"secrets":{scanner,inventory,env_set,stores}}.
# The secret inventory is the same name-only scanner as detect_local.sh (embedded below as base64, run with node or bun;
# without either, "scanner":"none"). env_set: candidate names set in this process or in the User/Machine environment
# (tested for non-empty, never printed). stores: Credential Manager target names containing "Codex Auth" (cmdkey /list,
# names only). Windows keeps Claude's login in a file (%USERPROFILE%\.claude\.credentials.json), not Credential Manager.
# Files checked per CLI: codex auth.json .credentials.json config.toml AGENTS.md prompts/ skills/ rules/;
# claude .credentials.json settings.json CLAUDE.md agents/ commands/ skills/ hooks/ ../.claude.json;
# pi auth.json .env *auth*.json *token*.json *credential*.json web-search*.json settings.json models.json hud.json
# .pi-lens.json trust.json AGENTS.md prompts/ skills/ extensions/ themes/ agents/ workflows/ workflow-profiles/ memory/;
# omp agent.db agent.db-wal agent.db-shm config.yml models.yml mcp.json AGENTS.md.
param([string[]]$Clis = @("claude", "codex", "pi", "omp"), [switch]$NoUserEnv)
$ErrorActionPreference = "SilentlyContinue"
$Clis = @($Clis | ForEach-Object { $_ -split "," } | Where-Object { $_ })
$H = $env:USERPROFILE
$SCAN_B64 = ""

function Get-Ver($c) {
  $j = Start-Job -ScriptBlock { param($x) (& $x --version 2>&1 | Select-Object -First 1) -as [string] } -ArgumentList $c
  if (Wait-Job $j -Timeout 10) { $v = Receive-Job $j } else { $v = "" }
  Remove-Job $j -Force
  if ($v) { $v = ($v -replace "[\x00-\x1f]", ""); if ($v.Length -gt 80) { $v = $v.Substring(0, 80) } }
  return [string]$v
}
function Get-OmpAuth($d) { # @{provider = usable|disabled}; needs sqlite3.exe; reads a temp copy, never the data column
  $r = [ordered]@{}
  if (-not (Get-Command sqlite3 -ErrorAction SilentlyContinue)) { return $r }
  $t = Join-Path ([IO.Path]::GetTempPath()) ("omp-detect-" + [guid]::NewGuid())
  New-Item -ItemType Directory -Path $t | Out-Null
  foreach ($n in "agent.db", "agent.db-wal", "agent.db-shm") { if (Test-Path "$d\$n") { Copy-Item "$d\$n" "$t\$n" } }
  $rows = & sqlite3 -batch -noheader -list "$t\agent.db" "select provider, case when disabled_cause is null then 'usable' else 'disabled' end from auth_credentials;" 2>$null
  Remove-Item -Recurse -Force $t
  foreach ($row in @($rows)) { $p = "$row".Split("|"); if ($p.Count -eq 2) { if ($p[1] -eq "usable" -or -not $r.Contains($p[0])) { $r[$p[0]] = $p[1] } } }
  return $r
}

$out = [ordered]@{ os = "windows"; home = $H; clis = [ordered]@{} }
foreach ($c in $Clis) {
  switch ($c) {
    "codex"  { $d = if ($env:CODEX_HOME) { $env:CODEX_HOME } else { "$H\.codex" }; $auth = @("auth.json", ".credentials.json"); $conf = @("config.toml"); $extra = @("AGENTS.md", "prompts/", "skills/", "rules/") }
    "claude" { $d = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { "$H\.claude" }; $auth = @(".credentials.json"); $conf = @("settings.json"); $extra = @("CLAUDE.md", "agents/", "commands/", "skills/", "hooks/") }
    "pi"     { $d = if ($env:PI_CODING_AGENT_DIR) { $env:PI_CODING_AGENT_DIR } else { "$H\.pi\agent" }; $auth = @("auth.json", ".env")
               foreach ($g in "*auth*.json", "*token*.json", "*credential*.json", "web-search*.json") {
                 Get-ChildItem -Path $d -Filter $g -File -Force | ForEach-Object { if ($_.Name -ne "auth.json" -and $_.Name -ne "oauth.json" -and $auth -notcontains $_.Name) { $auth += $_.Name } } }
               $conf = @("settings.json", "models.json", "hud.json", ".pi-lens.json", "trust.json")
               $extra = @("AGENTS.md", "prompts/", "skills/", "extensions/", "themes/", "agents/", "workflows/", "workflow-profiles/", "memory/", "packages/") }
    "omp"    { $d = "$H\.omp\agent"; $auth = @("agent.db"); $conf = @("config.yml", "models.yml", "mcp.json"); $extra = @("AGENTS.md") }
    default  { continue }
  }
  $present = @(); $hasAuth = $false; $hasConf = $false; $links = 0; $note = ""; $astat = [ordered]@{}; $lstore = "none"
  $inst = [bool](Get-Command $c -ErrorAction SilentlyContinue); $v = if ($inst) { Get-Ver $c } else { "" }
  foreach ($f in $auth) { if (Test-Path -LiteralPath "$d\$f" -PathType Leaf) { $hasAuth = $true; $present += $f } }
  foreach ($f in $conf) { if (Test-Path -LiteralPath "$d\$f" -PathType Leaf) { $hasConf = $true; $present += $f } }
  foreach ($f in $extra) {
    if ($f.EndsWith("/")) { $n = $f.TrimEnd("/")
      if ((Test-Path -LiteralPath "$d\$n" -PathType Container) -and (Get-ChildItem -LiteralPath "$d\$n" -Force | Select-Object -First 1)) {
        $present += $f; $links += @(Get-ChildItem -LiteralPath "$d\$n" -Force | Where-Object { $_.LinkType }).Count } }
    elseif (Test-Path -LiteralPath "$d\$f" -PathType Leaf) { $present += $f }
  }
  $imp = $hasAuth
  if ($c -eq "claude" -and (Test-Path -LiteralPath "$H\.claude.json")) { $present += "../.claude.json" }
  if ($hasAuth) { $lstore = "file" }
  if ($c -eq "omp" -and (Test-Path "$d\agent.db")) {
    foreach ($n in "agent.db-wal", "agent.db-shm") { if (Test-Path "$d\$n") { $present += $n } }
    if (Get-Process -Name omp -ErrorAction SilentlyContinue) { $note = "omp is running: quit it before copying agent.db" }
    $astat = Get-OmpAuth $d
    $good = @($astat.Keys | Where-Object { $astat[$_] -eq "usable" })
    foreach ($p in @($astat.Keys | Where-Object { $astat[$_] -eq "disabled" })) { $note = ($note + "; omp login for $p is disabled on this computer: run omp, then /login there first").TrimStart("; ") }
    if ($astat.Count -gt 0 -and $good.Count -eq 0) { $imp = $false }
  }
  if ($c -eq "codex" -and $env:CODEX_HOME -and $env:CODEX_HOME.TrimEnd("\") -ne "$H\.codex") { $note = "CODEX_HOME is set: copy per file" }
  if ($c -eq "claude" -and $env:CLAUDE_CONFIG_DIR -and $env:CLAUDE_CONFIG_DIR.TrimEnd("\") -ne "$H\.claude") { $note = "CLAUDE_CONFIG_DIR is set: copy per file" }
  $out.clis[$c] = [ordered]@{ installed = $inst; version = $v; dir = $d; has_auth = $hasAuth; importable_auth = $imp; has_config = $hasConf
    login_store = $lstore; present = @($present); symlinks = $links; auth_status = $astat; note = $note }
}

# ---- name-only secret inventory (same scanner as detect_local.sh)
$scanner = "none"; $inv = "{}"; $names = @()
$rt = @("node", "bun") | Where-Object { Get-Command $_ -ErrorAction SilentlyContinue } | Select-Object -First 1
if ($rt) {
  $t = Join-Path ([IO.Path]::GetTempPath()) ("detect-scan-" + [guid]::NewGuid() + ".js")
  [IO.File]::WriteAllBytes($t, [Convert]::FromBase64String($SCAN_B64))
  $cd = if ($env:CODEX_HOME) { $env:CODEX_HOME } else { Join-Path $H ".codex" }; $ld = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $H ".claude" }
  $pd = if ($env:PI_CODING_AGENT_DIR) { $env:PI_CODING_AGENT_DIR } else { Join-Path (Join-Path $H ".pi") "agent" }
  $raw = @(& $rt $t $H $cd $ld $pd (Join-Path (Join-Path $H ".omp") "agent") @Clis 2>$null)
  Remove-Item -Force $t
  $scanner = $rt
  foreach ($l in $raw) { if ("$l".StartsWith("NAMES ")) { $names = @("$l".Substring(6).Split(" ") | Where-Object { $_ -match '^[A-Za-z_][A-Za-z0-9_]*$' }) } elseif ("$l".StartsWith("{")) { $inv = "$l" } }
}
$es = [ordered]@{}
foreach ($n in $names) {
  if ([Environment]::GetEnvironmentVariable($n, "Process")) { $es[$n] = "process" }
  elseif (-not $NoUserEnv -and [Environment]::GetEnvironmentVariable($n, "User")) { $es[$n] = "user_env" }
  elseif (-not $NoUserEnv -and [Environment]::GetEnvironmentVariable($n, "Machine")) { $es[$n] = "machine_env" }
}
$targets = (cmdkey /list 2>$null | Select-String -Pattern "Target:" | ForEach-Object { "$_" }) -join "`n"
$stores = [ordered]@{ "Claude Code-credentials" = $false; "Codex Auth" = [bool]($targets -match "Codex Auth"); "Codex MCP Credentials" = [bool]($targets -match "Codex MCP Credentials") }
$sec = [ordered]@{ scanner = $scanner; inventory = "@@INV@@"; env_set = $es; stores = $stores }
$out.secrets = $sec
$json = $out | ConvertTo-Json -Depth 8 -Compress
$json.Replace('"@@INV@@"', $inv)
